class BusinessCategory { const BusinessCategory({required this.id, required this.name, required this.slug}); final String id; final String name; final String slug; }
class QueueSummary { const QueueSummary({required this.status, required this.peopleWaiting, required this.estimatedWaitingTimeMinutes, required this.averageServiceTimeMinutes, this.id, this.currentNumber}); final String? id; final String status; final String? currentNumber; final int peopleWaiting; final int estimatedWaitingTimeMinutes; final int averageServiceTimeMinutes; }
class BusinessServiceItem { const BusinessServiceItem({required this.id, required this.name, this.estimatedDurationMinutes, this.price}); final String id; final String name; final int? estimatedDurationMinutes; final num? price; }
class Business { const Business({required this.id, required this.name, required this.address, required this.category, required this.queue, this.description, this.imageUrl, this.rating, this.distanceKm, this.openingHours, this.services = const []}); final String id; final String name; final String address; final BusinessCategory category; final QueueSummary queue; final String? description; final String? imageUrl; final num? rating; final num? distanceKm; final Object? openingHours; final List<BusinessServiceItem> services; }